<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {api,errorMessage} from '../api/http'
const route=useRoute(),router=useRouter(),detail=ref<any>(null),id=String(route.params.id)
onMounted(async()=>{try{detail.value=await api('/sales/'+id)}catch(e){ElMessage.error(errorMessage(e))}})
</script>
<template><h1 class="page-title">受注詳細</h1><div class="toolbar"><el-button @click="router.push('/sales')">← 一覧に戻る</el-button><el-button type="primary" @click="router.push('/sales/'+id+'/documents')">帳票を見る</el-button></div><template v-if="detail"><section class="panel"><header class="panel-heading">基本情報</header><div class="panel-body"><el-descriptions :column="2" border><el-descriptions-item label="受注No.">{{detail.order.order_no}}</el-descriptions-item><el-descriptions-item label="取引先">{{detail.order.customer_name}}</el-descriptions-item><el-descriptions-item label="受注日">{{detail.order.order_date}}</el-descriptions-item><el-descriptions-item label="受注状態">{{detail.order.order_status}}</el-descriptions-item><el-descriptions-item label="金額">{{detail.order.total_amount}} {{detail.order.currency_code}}</el-descriptions-item><el-descriptions-item label="希望納期">{{detail.order.delivery_due_date||'—'}}</el-descriptions-item></el-descriptions></div></section><section class="panel"><header class="panel-heading">販売明細</header><div class="panel-body"><el-table :data="detail.items" border><el-table-column prop="line_no" label="No." width="65"/><el-table-column prop="product_name" label="設備名"/><el-table-column prop="model_no" label="型番"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="unit_price" label="単価"/><el-table-column prop="line_amount" label="金額"/></el-table></div></section></template><el-empty v-else description="読み込み中..."/></template>
